import { Component, JSX, splitProps } from 'solid-js';
import * as StickyParallaxScrollPrimitive from '@exhuma/core';

export interface StickyParallaxScrollProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const StickyParallaxScroll: Component<StickyParallaxScrollProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <StickyParallaxScrollPrimitive.StickyParallaxScroll
      class={`relative w-full overflow-hidden ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </StickyParallaxScrollPrimitive.StickyParallaxScroll>
  );
};

