import { StickyParallaxScroll } from '@exhuma/core';

export function initStickyParallaxScroll(selector = '[data-exhuma-sticky-parallax]', options = {}) {
  const elements = document.querySelectorAll(selector);
  return Array.from(elements);
}

webcomponent.code:
import { StickyParallaxScroll } from '@exhuma/core';

class ExhumaStickyParallaxScrollElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-sticky-parallax');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-sticky-parallax')) {
  customElements.define('exhuma-sticky-parallax', ExhumaStickyParallaxScrollElement);
}

react-native.code:
import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as StickyParallaxScrollPrimitive from '@exhuma/core';

export interface StickyParallaxScrollProps extends ViewProps {
  children?: React.ReactNode;
}

export function StickyParallaxScroll({ style, children, ...props }: StickyParallaxScrollProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

